import React from "react";
import type { StickerProps } from "../../types";
import { AnimatedSticker } from "../../components/AnimatedSticker";

// Exact reference pixels embedded as a lossless PNG — same technique as CatbeatsSticker.
const IMAGE = "data:image/png;base64,";

/**
 * Spooky Monster Stack Sticker — reproduced from the original Dribbble reference artwork.
 * Text, if any, is baked into the artwork and is not configurable.
 */
export const SpookyMonsterStackSticker: React.FC<StickerProps> = (props) => (
  <AnimatedSticker
    {...props}
    label="Spooky Monster Stack Sticker"
    viewBox="0 0 181 320"
    motion="bob"
    duration={3.6}
    origin="91px 320px"
  >
    <image href={IMAGE} x={0} y={0} width={181} height={320} />
  </AnimatedSticker>
);

export default SpookyMonsterStackSticker;
